  f=fac(i); y=P.iloc[i+h]/P.iloc[i]-1
  z=pd.DataFrame({'f':f,'y':y}).replace([np.inf,-np.inf],np.nan).dropna()
  if len(z)>=8 and z.f.nunique()>1:
   rows.append((P.index[i],len(z),z.f.corr(z.y,method='spearman')))
  if h==10:
