U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
C={}
for s in U:
 d=get_stock_daily_data(s,days=4000); d.date=pd.to_datetime(d.date)
 C[s]=d.sort_values('date').drop_duplicates('date').set_index('date').close.astype(float)
P=pd.DataFrame(C).sort_index(); R=np.log(P).diff()
def raw(i):
 res=R.iloc[:i+1].sub(R.iloc[:i+1].median(axis=1),axis=0)
 rev=res.iloc[i-4:i+1].sum(); vol=res.iloc[i-19:i+1].std()*np.sqrt(20); base=res.iloc[i-59:i-20].std()*np.sqrt(40)
 return -rev/(vol+1e-12)*np.clip(vol/(base+1e-12),.75,1.75)
# Adaptive regime gate: use only already-realized 5d IC observations from dates i-65..i-6.
def gated(i):
 f=raw(i); hist=[]
 for j in range(i-65,i-4):
  if j<60: continue
  z=pd.DataFrame({'f':raw(j),'y':P.iloc[j+5]/P.iloc[j]-1}).dropna()
  if len(z)>=8 and z.f.nunique()>1: hist.append(z.f.corr(z.y,method='spearman'))
 gate=1.0 if len(hist)<20 or np.nanmean(hist)>=0 else -1.0
 return f*gate
rows=[]; sig=[]
for i in range(130,len(P)-5):
 f=gated(i); y=P.iloc[i+5]/P.iloc[i]-1; z=pd.DataFrame({'f':f,'y':y}).replace([np.inf,-np.inf],np.nan).dropna()
 if len(z)>=8 and z.f.nunique()>1:
  rows.append((P.index[i],len(z),z.f.corr(z.y,method='spearman')))
  for s,a in f.items(): sig.append({'date':str(P.index[i].date()),'symbol':s,'signal':float(a)})
x=pd.DataFrame(rows,columns=['date','n','ic']).dropna(); m=x.ic.mean(); sd=x.ic.std(ddof=1)
print('candidate=adaptive_vol_shock_residual_reversal_5d','assets',15,'dates',len(x),'meanN',round(x.n.mean(),2),'coverage',round(x.n.sum()/(len(x)*15),5),'IC',round(m,6),'ICIR',round(m/sd,6),'hit',round((x.ic>0).mean(),5))
for a,b in [('2020-01-01','2024-12-31'),('2025-01-01','2027-12-31'),('2028-01-01','2029-12-31'),('2030-01-01','2031-02-19')]:
 q=x[(x.date>=a)&(x.date<=b)]; print('regime',a,b,'dates',len(q),'IC',round(q.ic.mean(),6),'ICIR',round(q.ic.mean()/q.ic.std(ddof=1),6) if len(q)>1 else np.nan)
S=pd.DataFrame(sig).pivot(index='date',columns='symbol',values='signal'); print('turnover',round(S.rank(axis=1,pct=True).diff().abs().mean(axis=1).dropna().mean(),6),'cutoff',P.index[-1].date())
