P=pd.DataFrame(px).sort_index(); r=P.pct_change()
# Penalize downside-risk assets: fade recent return divided by downside semideviation.
down=r.where(r<0,0.0)
downvol=down.rolling(40,min_periods=25).std()
ret20=P.pct_change(20)
sig=(-ret20/(downvol*np.sqrt(20)+1e-12)).clip(-8,8)
print('assets',len(P.columns),'rows',len(P))
for h in [5,10,20]:
