import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cl={};vo={}
for s in U:
 d=get_stock_daily_data(s,3000)
 if d is not None and len(d)>=100:
  x=d.set_index('date');cl[s]=x.close.astype(float);vo[s]=x.volume.astype(float)
P=pd.DataFrame(cl).sort_index();V=pd.DataFrame(vo).reindex(P.index)
r=P.pct_change(); cs=r.sub(r.mean(axis=1),axis=0)
base=(-cs.rolling(10,min_periods=8).sum()/(cs.rolling(40,min_periods=25).std()*np.sqrt(10)+1e-12)).clip(-8,8)
lv=np.log1p(V.clip(lower=0)); vz=(lv-lv.rolling(40,min_periods=25).mean())/(lv.rolling(40,min_periods=25).std()+1e-12)
# causal downside/upside activity imbalance: recent negative-return volume shocks strengthen reversal
neg=(r<0).astype(float); pos=(r>0).astype(float)
down=(vz*neg).rolling(10,min_periods=5).mean(); up=(vz*pos).rolling(10,min_periods=5).mean()
asym=np.tanh(down-up)
sig=base*(1+0.40*asym).clip(.60,1.40)
print('assets',len(P.columns),'rows',len(P))
def ev(h):
 q=P.shift(-h)/P-1;a=[];ds=[];ns=[]
 for dt in sig.index:
  z=pd.concat([sig.loc[dt],q.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   c=z.iloc[:,0].corr(z.iloc[:,1],method='spearman')
   if np.isfinite(c):a.append(c);ds.append(dt);ns.append(len(z))
 return np.asarray(a),pd.DatetimeIndex(ds),np.asarray(ns)
for h in [5,10,20]:
 a,ds,ns=ev(h);print('horizon',h,'dates',len(a),'start',ds[0].date(),'end',ds[-1].date(),'mean_n',round(ns.mean(),3),'coverage',round(ns.mean()/15,6),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),6))
 if h==10:
  for x,y in [('2023-08-23','2025-12-31'),('2026-01-01','2027-12-31'),('2028-01-01','2030-12-31'),('2031-01-01','2035-03-20')]:
   z=a[(ds>=pd.Timestamp(x))&(ds<=pd.Timestamp(y))];print('regime',x,y,'dates',len(z),'IC',round(z.mean(),6) if len(z) else None)
  ranks=pd.DataFrame([sig.loc[d].rank(pct=True) for d in ds],index=ds);print('turnover',round(ranks.diff().abs().mean().mean(),6))
  pd.DataFrame([(dt,s,float(sig.loc[dt,s])) for dt in sig.index for s in sig.columns if pd.notna(sig.loc[dt,s])],columns=['date','symbol','factor_value']).to_csv('scripts/miner_1_20350329_downside_volume_asymmetry_reversal_signal.csv',index=False)

