import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 d=get_stock_daily_data(s,3300)
 if d is not None and len(d)>=160: D[s]=d.set_index('date')
C=pd.DataFrame({s:x.close.astype(float) for s,x in D.items()}).sort_index(); R=C.pct_change()
bench=R.mean(axis=1); E=R.sub(bench,axis=0)
# Efficient residual trend: cumulative residual return divided by residual path length,
# then scaled by trailing residual risk. All rolling inputs are lagged at decision date.
cum=E.rolling(20,min_periods=15).sum()
path=E.abs().rolling(20,min_periods=15).sum()
eff=(cum/(path+1e-12)).clip(-1,1)
risk=E.rolling(40,min_periods=25).std()
sig=(cum/(risk*np.sqrt(20)+1e-12)*eff).replace([np.inf,-np.inf],np.nan)
for h in [5,10,20]:
 q=C.shift(-h)/C-1; vals=[]; ds=[]; ns=[]
 for dt in sig.index:
  z=pd.concat([sig.loc[dt],q.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   c=z.iloc[:,0].corr(z.iloc[:,1],method='spearman')
   if np.isfinite(c): vals.append(c);ds.append(dt);ns.append(len(z))
 a=np.array(vals); ds=pd.DatetimeIndex(ds); ns=np.array(ns)
 if len(a):
  print('h',h,'dates',len(a),'meanN',round(ns.mean(),3),'coverage',round(ns.mean()/15,6),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),6))
  if h==10:
   for aa,bb in [('2020-01-01','2022-12-31'),('2023-01-01','2025-12-31'),('2026-01-01','2028-12-31'),('2029-01-01','2031-12-31'),('2032-01-01','2035-11-20')]:
    w=a[(ds>=aa)&(ds<=bb)]; print('regime',aa,bb,len(w),round(w.mean(),6) if len(w) else None)
   ranks=pd.DataFrame([sig.loc[d].rank(pct=True) for d in ds],index=ds)
   print('turnover',round(ranks.diff().abs().mean().mean(),6))
   pd.DataFrame([(dt,s,float(sig.loc[dt,s])) for dt in sig.index for s in sig.columns if pd.notna(sig.loc[dt,s])],columns=['date','symbol','factor_value']).to_csv('scripts/miner_1_20351122_efficient_residual_trend_signal.csv',index=False)
print('assets',len(C.columns),'rows',len(C),'start',C.index.min().date(),'end',C.index.max().date())

import pandas as pd, numpy as np, os
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 p='../persistent/stock_data/'+s+'.csv'
 if os.path.exists(p): D[s]=pd.read_csv(p,parse_dates=['date']).set_index('date')['close'].replace(0,np.nan)
px=pd.concat(D,axis=1).sort_index(); r=px.pct_change(); bench=r.mean(axis=1)
res10=px.pct_change(10).sub(px.pct_change(10).mean(axis=1),axis=0)
# Stress-conditioned residual reversal: amplify reversal when recent cross-asset dispersion is elevated.
disp=r.rolling(10,min_periods=8).std().mean(axis=1)
base=disp.rolling(120,min_periods=60).median()
mult=(disp/base).clip(.6,1.8)
factor=-res10.mul(mult,axis=0)
rows=[]
for i in range(130,len(px)-10):
 z=pd.concat([factor.iloc[i],px.iloc[i+10]/px.iloc[i]-1],axis=1).dropna()
 if len(z)>=8: rows.append((px.index[i],spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic,len(z)))
a=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date')
print('dates',len(a),'meanN',a.n.mean(),'coverage',a.n.mean()/15)
print('h10 IC %.6f ICIR %.6f hit %.4f turnover %.6f'%(a.ic.mean(),a.ic.mean()/a.ic.std(ddof=1),(a.ic>0).mean(),factor.rank(axis=1,pct=True).diff().abs().mean().mean()))
for lo,hi in [('2020','2022-12-31'),('2023','2025-12-31'),('2026','2028-12-31'),('2029','2031-12-31'),('2032','2035-12-05')]:
 q=a.loc[lo:hi].ic; print(lo,hi,'n',len(q),'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1) if len(q)>1 else np.nan)
for h in [5,20]:
 rr=[]
 for i in range(130,len(px)-h):
  z=pd.concat([factor.iloc[i],px.iloc[i+h]/px.iloc[i]-1],axis=1).dropna()
  if len(z)>=8: rr.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 print('h',h,'dates',len(rr),'IC',np.mean(rr),'ICIR',np.mean(rr)/np.std(rr,ddof=1))
out=factor.copy(); out.index.name='date'; out.to_csv('scripts/miner_1_20351206_dispersion_scaled_residual_reversal_signal.csv')

